(r/'tools/CropGoalCheck.java').write_text('''package net.minecraftforge.registries;import org.millenaire.common.goal.generic.GoalGenericPlantCrop;import org.millenaire.common.utilities.Point;import org.millenaire.common.entity.MillVillager;import org.millenaire.common.village.Building;import org.millenaire.common.item.InvItem;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.Items;import java.util.*;
public class CropGoalCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void reset(MillVillager v){Point.cells.clear();v.destination=new Point(-4,-40,2);v.house=new Building();v.seeds=0;v.swings=0;Point.cells.put(v.destination.pos.below(),Blocks.DIRT.defaultBlockState());}
 public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);var unsafe=(sun.misc.Unsafe)f.get(null);var v=(MillVillager)unsafe.allocateInstance(MillVillager.class);var goal=new GoalGenericPlantCrop();goal.soilType=new ResourceLocation("farmland");goal.cropType=new ResourceLocation("wheat");goal.seed=new InvItem(Items.WHEAT_SEEDS);
  reset(v);v.seeds=1;goal.performAction(v);check(v.seeds==0&&v.swings==1&&Point.cells.get(v.destination.pos).is(Blocks.WHEAT)&&Point.cells.get(v.destination.pos.below()).is(Blocks.FARMLAND),"Seed and soil conversion at negative height");goal.performAction(v);check(v.swings==1,"Existing crop not replanted");
  reset(v);v.house.seeds=1;goal.performAction(v);check(v.house.seeds==0&&Point.cells.get(v.destination.pos).is(Blocks.WHEAT),"Building seed fallback");
  reset(v);goal.performAction(v);check(!Point.cells.containsKey(v.destination.pos)&&Point.cells.get(v.destination.pos.below()).is(Blocks.DIRT),"No free crop without seed");
  reset(v);v.seeds=1;Point.cells.put(v.destination.pos.above(),Blocks.STONE.defaultBlockState());goal.performAction(v);check(v.seeds==1&&v.swings==0,"Headroom obstruction preserved");
  reset(v);v.seeds=1;Point.cells.put(v.destination.pos.below(),Blocks.STONE.defaultBlockState());Point.cells.put(v.destination.pos,Blocks.GRASS.defaultBlockState());goal.performAction(v);check(v.seeds==1&&v.swings==0,"Decorative plant does not bypass soil restriction");
  reset(v);v.seeds=1;Point.cells.put(v.destination.pos,Blocks.TALL_GRASS.defaultBlockState());Point.cells.put(v.destination.pos.above(),Blocks.TALL_GRASS.defaultBlockState().setValue(DoublePlantBlock.HALF,DoubleBlockHalf.UPPER));goal.performAction(v);check(v.seeds==0&&Point.cells.get(v.destination.pos).is(Blocks.WHEAT),"Two-block decorative vegetation can be cleared");
  for(Block plant:new Block[]{Blocks.ROSE_BUSH,Blocks.SUNFLOWER}){reset(v);goal.seed=null;goal.cropType=new ResourceLocation("flower");goal.soilType=new ResourceLocation("dirt");goal.plantBlockState=List.of(plant.defaultBlockState().setValue(DoublePlantBlock.HALF,DoubleBlockHalf.UPPER));goal.performAction(v);check(Point.cells.get(v.destination.pos).getValue(DoublePlantBlock.HALF)==DoubleBlockHalf.LOWER&&Point.cells.get(v.destination.pos.above()).getValue(DoublePlantBlock.HALF)==DoubleBlockHalf.UPPER,"Two-block halves normalized");}
  reset(v);goal.plantBlockState=List.of(Blocks.POPPY.defaultBlockState());Point.cells.put(v.destination.pos,Blocks.BLUE_ORCHID.defaultBlockState());goal.performAction(v);check(v.swings==0&&Point.cells.get(v.destination.pos).is(Blocks.BLUE_ORCHID),"Existing flower retained");
  v.destination=null;check(goal.performAction(v),"Missing destination safe");
  System.out.println("PASS: actual crop goal with world/inventory fixtures: negative height, soil conversion, villager/building seeds, no free crops, existing crops/flowers, solid headroom, soil restriction, two-block halves and null destination. Live block updates, grapes and failed world writes untested.");
 }
}''',encoding='utf-8')
